# flake8: noqa

import collections
import multiprocessing
import select
import socket
import threading
import time

import ta_emss.utilities.xterm_lib.asncoder as asncoder
import ta_emss.utilities.xterm_lib.message_def as message_def
import ta_emss.utilities.xterm_lib.message_rrc_def as message_rrc_def
import ta_emss.utilities.xterm_lib.xsocket as xsocket
from ta_emss.utilities.xterm_lib.flogger import Flogger
from ta_emss.utilities.xterm_lib.defs import *

g_debug = False
g_enable_prints = False


class BTSClient(threading.Thread):
    def __init__(self, client, ip_addr, amf_config, logger=None, log_screen=True, log_file=True, parent_sch=None):
        super(BTSClient, self).__init__()
        self.client = client
        self.ip_addr = ip_addr
        self.amf_config = amf_config
        self.running = False
        self.logger = logger
        self.num_msg_rx = 0
        self.num_msg_tx = 0
        self.hb = 0
        self.errors = 0
        self.link_state = LS_INIT  # "INIT", "CONNECTED", "CLOSED"
        self.ip_addr_str = str(self.ip_addr)
        self.server_ip_addr_str = str(self.amf_config["AMF_IP_ADDR"])
        self.asn_coder = asncoder.ASNCoder(protocol="NGAP")
        self.ue_seq_num = {}

        self.log_screen = log_screen
        self.log_file = log_file
        self.parent_sch = parent_sch
        self.amf_id = amf_config["AMF_ID"]

    def desc(self):
        return "[{}] (hb:{}, rx:{}, tx:{}, err:{}, state:{})".format(
            self.ip_addr,
            self.hb,
            self.num_msg_rx,
            self.num_msg_tx,
            self.errors,
            self.link_state,
        )

    def run(self):
        self.running = True
        self.client.settimeout(1)
        input = [self.client]
        select_timeout = 60
        while self.running:
            self.hb += 1
            if self.errors:
                self.log("Errors exist. Closing connection...")
                self.running = False
                break

            try:
                inputready, outputready, exceptready = select.select(input, [], [], select_timeout)
                if len(inputready):
                    data = xsocket.recv(self.client)
                    if data:
                        msg_hex = data.hex().upper()
                        self.process_msg(msg_hex)
                    else:
                        self.running = False
                        break
            except socket.timeout as err:
                self.logerror("Socket timeout: {}".format(err))
            except socket.error as err:
                self.logerror("Socket error:{}".format(err))
                self.running = False
            except select.error as err:
                self.logerror("Select error: {}.".format(err))

        self.running = False
        if self.client:
            self.client.close()
            self.client = None
        self.link_state = LS_CLOSED
        self.log("NGAP Client disconnected {}...".format(self.ip_addr_str))

    def send_msg(self, msg_hex, msg_desc):
        if not self.client:
            self.logerror("Cannot send message {} - no client connected.".format(msg_desc))
            return 0
        try:
            self.log("<--- Sending NGAP {}".format(msg_desc))
            self.logfile("<--- DATA SENT=[%s]\n" % msg_hex)
            xsocket.send(self.client, bytes.fromhex(msg_hex))
            self.num_msg_tx += 1
        except Exception as exc:
            self.logerror("Unable to send NGAP {} ({}).".format(msg_desc, exc))
            return 0
        return 1

    def is_running(self):
        return self.running

    def stop(self):
        self.running = False

    def process_msg(self, msg_hex):
        recv_msg = "---> Received NGAP "
        self.num_msg_rx += 1
        msg = self.asn_coder.decode_asn(msg_hex)
        if g_debug:
            self.logfile("NGAP: Received message:\n[{}]\n{}\n".format(msg_hex, msg))

        if msg.find("ERROR: decoding failed") != -1:
            self.logwarn("ASN decoding failed.")
            self.logfile("---> DATA RECV=[%s]\n" % msg_hex)

        elif msg.find("NGSetupResponse") != -1:
            self.log(recv_msg + "NGSetupResponse")
            self.link_state = LS_CONNECTED

        elif msg.find("NGSetupFailure") != -1:
            self.logerror(recv_msg + "NGSetupFailure")
            self.link_state = LS_INIT

        elif msg.find("NGSetupRequest") != -1:
            self.log(recv_msg + "NGSetupRequest")
            msg_str = message_def.NGSetupResponse(self.amf_config)
            if g_debug:
                self.logfile("Sending NGSetupResponse={}".format(msg_str))
            msg_hex_enc = self.asn_coder.encode_asn(msg_str)
            if self.send_msg(msg_hex_enc, "NGSetupResponse"):
                self.link_state = LS_CONNECTED

        elif msg.find("InitialUEMessage") != -1:
            self.log(recv_msg + "InitialUEMessage")
            self.process_InitialUEMessage(msg)

        elif msg.find("UplinkNASTransport") != -1:
            self.log(recv_msg + "UplinkNASTransport")
            self.process_UplinkNASTransport(msg)

        elif msg.find("UEContextReleaseComplete") != -1:
            self.log(recv_msg + "UEContextReleaseComplete")
            self.process_UEContextReleaseComplete(msg)

        elif msg.find("UEContextReleaseRequest") != -1:
            self.log(recv_msg + "UEContextReleaseRequest")
            self.process_UEContextReleaseRequest(msg)

        else:
            self.log(recv_msg + "Unknown")
            self.log(msg)

    def get_next_ue_seq_num(self, ue_id):
        if ue_id in self.ue_seq_num:
            ret = self.ue_seq_num[ue_id]
            self.ue_seq_num[ue_id] += 1
            return ret
        self.log("Cannot get seq_num for UE-{}: No such UE.".format(ue_id))
        return None

    def process_InitialUEMessage(self, msg):
        ue_id = self.asn_coder.extract_ran_ue_ngap_id(msg)
        amf_config = self.amf_config
        amf_config["UE_ID"] = ue_id
        amf_config["NAS_PDU"] = message_rrc_def.AMF_NAS_PDUs["Authentication-request"]

        if g_debug:
            self.log("[UE-{}] Processing InitialUEMessage".format(ue_id))

        msg_str = message_def.NGDownlinkNASTransport(amf_config)
        if g_debug:
            self.logfile("Sending DownlinkNASTransport={}".format(msg_str))
        msg_hex_enc = self.asn_coder.encode_asn(msg_str)
        self.send_msg(msg_hex_enc, "DownlinkNASTransport (UE-{})".format(ue_id))
        self.ue_seq_num[ue_id] = 0

    def process_UEContextReleaseComplete(self, msg):
        ue_id = self.asn_coder.extract_ran_ue_ngap_id(msg)
        if g_debug:
            self.log("[UE-{}] Processing UEContextReleaseComplete".format(ue_id))
        del self.ue_seq_num[ue_id]

    def process_UEContextReleaseRequest(self, msg):
        ue_id = self.asn_coder.extract_ran_ue_ngap_id(msg)
        if g_debug:
            self.log("[UE-{}] Processing UEContextReleaseRequest".format(ue_id))
        del self.ue_seq_num[ue_id]

    def process_UplinkNASTransport(self, msg):
        ue_id = self.asn_coder.extract_ran_ue_ngap_id(msg)
        amf_config = self.amf_config
        amf_config["UE_ID"] = ue_id
        amf_config["NAS_PDU"] = None

        seq_num = self.get_next_ue_seq_num(ue_id)
        if seq_num is None:
            return

        if g_debug:
            self.log("[UE-{}] Processing UplinkNASTransport: seq_num={}".format(ue_id, seq_num))

        try:
            if seq_num == 0:
                amf_config["NAS_PDU"] = message_rrc_def.AMF_NAS_PDUs["Security-mode-command"]
            elif seq_num == 1:
                amf_config["NAS_PDU"] = message_rrc_def.AMF_NAS_PDUs["Encrypted-data"]
            elif seq_num == 2:
                msg_pyasn = self.asn_coder.asn2py(msg)
                if g_debug:
                    self.log("UplinkNASTransport: pyasn={}".format(msg_pyasn))
                nas_pdu = msg_pyasn["NGAP-PDU"]["initiatingMessage"]["value"]["UplinkNASTransport"]["protocolIEs"][2]["value"]["NAS-PDU"]
                if nas_pdu == "0x7E0043":
                    self.log("[UE-{}] UplinkNASTransport: Registration complete".format(ue_id))
                    return
            else:
                msg_pyasn = self.asn_coder.asn2py(msg)
                if g_debug:
                    self.log("[UE-{}] UplinkNASTransport: pyasn={}".format(ue_id, msg_pyasn))
                nas_pdu = msg_pyasn["NGAP-PDU"]["initiatingMessage"]["value"]["UplinkNASTransport"]["protocolIEs"][2]["value"]["NAS-PDU"]
                if nas_pdu == "0xAABBCCDDEEFF":
                    self.release_ue_context(amf_config)
                    return
                elif nas_pdu == "0x" + "BB" * 22:
                    self.initial_context_setup(amf_config)
                    return

        except Exception as exc:
            self.log("[UE-{}] Exception in UplinkNASTransport processing: {}".format(ue_id, exc))

        if amf_config["NAS_PDU"]:
            msg_str = message_def.NGDownlinkNASTransport(amf_config)
            if g_debug:
                self.logfile("Sending DownlinkNASTransport={}".format(msg_str))
            msg_hex_enc = self.asn_coder.encode_asn(msg_str)
            self.send_msg(msg_hex_enc, "DownlinkNASTransport (UE-{}, seq_num={})".format(ue_id, seq_num))

    def release_ue_context(self, amf_config):
        msg_str = message_def.NGUEContextReleaseCommand(amf_config)
        if g_debug:
            self.logfile("Sending UEContextReleaseCommand={}".format(msg_str))
        msg_hex_enc = self.asn_coder.encode_asn(msg_str)
        ue_id = amf_config["UE_ID"]
        self.send_msg(msg_hex_enc, "UEContextReleaseCommand (UE-{})".format(ue_id))

    def initial_context_setup(self, amf_config):
        msg_str = message_def.NGInitialContextSetupRequest(amf_config)
        if g_debug:
            self.logfile("Sending InitialContextSetupRequest={}".format(msg_str))
        msg_hex_enc = self.asn_coder.encode_asn(msg_str)
        ue_id = amf_config["UE_ID"]
        self.send_msg(msg_hex_enc, "InitialContextSetupRequest (UE-{})".format(ue_id))

    def loginf(self):
        return "[Farend: " + str(self.ip_addr[0]) + " | Server: " + self.server_ip_addr_str + "] "

    def logfile(self, msg):
        msg_out = self.loginf() + str(msg)
        if not self.log_file:
            return msg_out
        if self.logger:
            msg_out = self.logger.write(msg_out)
            self.logger.flush_if_necessary()
        return msg_out

    def log(self, msg):
        msg_out = self.logfile(msg)
        if self.log_screen:
            print(msg_out)

    def logerror(self, msg):
        msg_out = "ERROR: " + msg
        self.log(msg_out)
        self.errors += 1

    def logwarn(self, msg):
        msg_out = "WARN: " + msg
        self.log(msg_out)


class SchedulerNg(multiprocessing.Process):
    def __init__(self, id, mdict, amfs, db, mp_pipe, mp_lock):
        super(SchedulerNg, self).__init__()
        self.id = id
        self.mdict = mdict
        self.db = db
        self.mp_pipe = mp_pipe
        self.mp_lock = mp_lock
        self.amfs = []

        self.port = 38412
        self.logger = None
        self.log_screen = db.log_screen
        self.log_file = db.log_file
        self.semaphore = threading.BoundedSemaphore()
        self.running = multiprocessing.Event()

        for i, amf in enumerate(amfs, start=1):
            amf["AMF_ID"] = i
            self.amfs.append(
                {
                    "AMF_CONFIG": amf,
                    "EPNGS": [],
                    "SERVER": None,
                }
            )

    def log_status(self):
        for amf in self.amf:
            amf_ip = amf["AMF_CONFIG"]["AMF_IP_ADDR"]
            for epng in amf["EPNGS"]:
                epng_desc = epng.desc()
                amf_is_running = epng.is_running()
                if amf_ip == epng.ip_addr:
                    self.logfile(
                        "{}, running=({}).".format(
                            epng_desc,
                            amf_is_running,
                        )
                    )
                else:
                    self.logfile("{}, running=({}).".format(epng_desc, amf_is_running))

    def stop(self):
        self.running.clear()

    def is_running(self):
        return self.running.is_set()

    def loginf(self):
        return f"[SCHng-{self.id}] "

    def log(self, msg):
        msg_out = self.logfile(msg)
        if self.db.log_screen:
            print(msg_out)

    def logfile(self, msg):
        msg_out = self.loginf() + str(msg)
        if not self.db.log_file:
            return msg_out
        if self.logger:
            msg_out = self.logger.write(msg_out)
            self.logger.flush_if_necessary()
        elif not self.running:
            pass
        else:
            self.logger = Flogger(self.db.get_logdir() + "/LOG-NGAP-SCH-"  + str(self.id) + ".log")
            self.logger.write("=" * 80)
            self.logger.write("LID=[SCHEDULER]")
            msg_out = self.logger.write(msg_out)
            self.logger.flush_now()
        return msg_out

    def logerror(self, msg):
        msg_out = "ERROR: " + msg
        self.log(msg_out)
        self.mdict["errors"] += 1

    def check_log(self):
        if self.mdict["log_screen"] != self.log_screen or self.mdict["log_file"] != self.log_file:
            self.set_log(log_screen=self.mdict["log_screen"], log_file=self.mdict["log_file"])

    def set_log(self, log_screen=True, log_file=True):
        if self.log_screen != log_screen:
            self.log_screen = log_screen
            self.set_amf_log()
        self.log_file = log_file
        self.log("Log to screen={}, log to file={}.".format(log_screen, log_file))

    def set_amf_log(self):
        for amf in self.amfs:
            for epng in amf["EPNGS"]:
                epng.log_screen = self.log_screen

    def update_status(self, req=False):
        if req:
            stime = time.time()
            #           if g_debug: self.log("Acquiring STAT mp_lock...")
            self.mp_lock.acquire()
        status = ""
        stat_ls_init = 0
        stat_ls_connected = 0
        stat_ls_closed = 0
        for i, amf in enumerate(self.amfs):
            for epng in amf["EPNGS"]:
                status += "  AMF({}):{}\n".format(i, epng.desc())
                if epng.link_state == LS_INIT:
                    stat_ls_init += 1
                elif epng.link_state == LS_CONNECTED:
                    stat_ls_connected += 1
                elif epng.link_state == LS_CLOSED:
                    stat_ls_closed += 1
        if not req:
            self.semaphore.acquire()
        self.mdict["status"] = status
        self.mdict["stat_ls_init"] = stat_ls_init
        self.mdict["stat_ls_connected"] = stat_ls_connected
        self.mdict["stat_ls_closed"] = stat_ls_closed
        if not req:
            self.semaphore.release()

        if req:
            self.mp_pipe.send("STAT")
            if self.mp_pipe.poll(5):
                ack = self.mp_pipe.recv_bytes()
            self.mp_lock.release()

    def check_server(self):
        inputs = []

        for amf in self.amfs:
            if amf["SERVER"]:
                inputs.append(amf["SERVER"])
            else:
                self.open_server_socket(amf)

            amf_id = amf["AMF_CONFIG"]["AMF_ID"]
            for epng in amf["EPNGS"][:]:
                if epng.link_state == LS_CLOSED:
                    if g_debug:
                        self.log("Joining closed epng for amf={} ({})...".format(amf_id, epng.desc()))
                    epng.join()
                    if g_debug:
                        self.log("Joined epng for amf={} ({})...".format(amf_id, epng.desc()))
                    amf["EPNGS"].remove(epng)

        self.update_status()

        if len(inputs) == 0:
            time.sleep(1)
            return True

        # select_timeout = 10 if self.start_scn else 30
        select_timeout = 1
        ret = True
        try:
            inputready, outputready, exceptready = select.select(inputs, [], [], select_timeout)
            if len(inputready):
                for inp in inputready:
                    for amf in self.amfs:
                        if inp == amf["SERVER"]:
                            try:
                                conn, addr = inp.accept()
                                self.log("NGAP Server: New connection to {}.".format(amf["AMF_CONFIG"]["AMF_IP_ADDR"]))
                                eclient = BTSClient(
                                    conn,
                                    addr,
                                    amf["AMF_CONFIG"],
                                    logger=self.logger,
                                    parent_sch=self,
                                    log_screen=self.log_screen,
                                    log_file=self.log_file,
                                )
                                eclient.start()
                                amf["EPNGS"].append(eclient)

                            except socket.timeout:
                                self.logerror("EPNG Server: Socket timeout, ip={}".format(amf["AMF_CONFIG"]["AMF_IP_ADDR"]))
                            except socket.error as err:
                                self.EPNG("EPNG Server: Socket error, ip={}: {}".format(amf["AMF_CONFIG"]["AMF_IP_ADDR"], err))
                                ret = False
                            except Exception as exc:
                                self.logerror("EPNG Server: Exception for incoming ip={}: {}.".format(amf["AMF_CONFIG"]["AMF_IP_ADDR"], exc))
                                ret = False

        except select.error as exc:
            self.logerror("EPNG Server: Select error: {}.".format(exc))
            ret = False
        except Exception as exc:
            self.logerror("EPNG Server: Select Exception: {}.".format(exc))
            ret = False
        return ret

    def open_server_sockets(self):
        for amf in self.amfs:
            self.open_server_socket(amf)

    def open_server_socket(self, amf):
        amf["SERVER"] = None
        ip_addr = amf["AMF_CONFIG"]["AMF_IP_ADDR"]
        amf_id = amf["AMF_CONFIG"]["AMF_ID"]
        try:
            sctp_sckt = socket.getprotobyname("sctp")
            if g_debug:
                self.log("Creating EPNG Server SCTP socket ({})...".format(amf_id))
            server = socket.socket(xsocket.get_socket_type(ip_addr), socket.SOCK_STREAM, sctp_sckt)
            server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            if g_debug:
                self.log("Binding EPNG Server SCTP socket to local ip addr={} ({}).".format(ip_addr, amf_id))
            server.bind((ip_addr, self.port))
            if g_enable_prints:
                self.log("EPNG Server listening on local ip addr={} ({}).".format(ip_addr, amf_id))
            server.listen(5)
            server.settimeout(0.1)
            amf["SERVER"] = server
        except socket.error as err:
            self.logerror("Could not open epng server socket for ip={} ({}): {}.".format(ip_addr, amf_id, err))
            if amf["SERVER"]:
                amf["SERVER"].close()
                amf["SERVER"] = None
        except Exception as exc:
            self.logerror("Exception-open_server_socket for ip={} ({}) [{}]".format(ip_addr, amf_id, exc))

    def run(self):
        self.open_server_sockets()
        self.running.set()

        while self.running.is_set():
            self.mdict["hb"] += 1
            self.check_server()
            self.update_status()
            self.check_log()

        self.log("Stopping scheduler...")
        for amf in self.amfs:
            if amf["SERVER"]:
                amf["SERVER"].close()
        for amf in self.amfs:
            for epng in amf["EPNGS"]:
                epng.stop()
                if g_debug:
                    self.log("Joining epng connection ({}-{})...".format(epng.amf_id, epng.ip_addr))
                epng.join()
                if g_debug:
                    self.log("Joined epng conn ({}-{}).".format(epng.amf_id, epng.ip_addr))
        self.log("SchedulerNG stopped.")
        self.running.clear()
